// Generated by `xark client` from `schema.json`: a typed client for the `merkle` circuit.
//
//   #[circuit]
//   fn merkle(leaf: Private<Field>, siblings: Private<[Field; 4]>, index_bits: Private<[Field; 4]>, root: Public<Field>)
//
// `xark build` records the circuit's parameter types in target/xark/merkle/schema.json
// and `xark client` turns them into the types below. Don't edit this file: change
// the circuit, then rebuild and rerun `xark client`. Values go in their natural
// forms (dates, strings, variant names, bytes); xark-wasm encodes them against the
// schema, exactly as `xark prove --inputs` does.

import { Circuit, Field, type Proof, type Prover, type Verifier } from "@blueshift-gg/xark-wasm/client";
export { Field };

/** Every input of `merkle`. */
export interface MerkleInputs {
  leaf: Field;
  /** Exactly 4 elements. */
  siblings: readonly Field[];
  /** Exactly 4 elements. */
  indexBits: readonly Field[];
  root: Field;
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface MerklePublicInputs {
  root: Field;
}

/** The public inputs, decoded from a proof. */
export interface MerklePublicValues {
  root: Field;
}

/**
 * `merkle`: make a prover or verifier with the xark-wasm module you pass in,
 * from a URL serving a copy of `target/xark/merkle/` (relative to the page in a
 * browser) or from the bytes:
 *
 * ```ts
 * import * as wasm from "@blueshift-gg/xark-wasm"; // node, web (after `await init()`), or bundler
 * const prover = await Merkle.prover(wasm, "/circuits/merkle/");
 * const proof = prover.prove(inputs);
 * send(proof.toBytes());
 * const verifier = await Merkle.verifier(wasm, vkBytes);
 * verifier.verify(proof.toBytes()); // true
 * ```
 */
export const Merkle = new Circuit<MerkleInputs, MerklePublicInputs, MerklePublicValues, {}>({
  name: "merkle",
  schema: "{\"circuit\":\"merkle\",\"inputs\":[{\"name\":\"leaf\",\"type\":\"field\",\"visibility\":\"private\"},{\"name\":\"siblings\",\"type\":{\"array\":{\"len\":4,\"of\":\"field\"}},\"visibility\":\"private\"},{\"name\":\"index_bits\",\"type\":{\"array\":{\"len\":4,\"of\":\"field\"}},\"visibility\":\"private\"},{\"name\":\"root\",\"type\":\"field\",\"visibility\":\"public\"}],\"public_inputs\":[\"root\"],\"types\":{},\"version\":2}",
  decodePublic,
  client: false,
});

export type MerkleProver = Prover<MerkleInputs, MerklePublicInputs, MerklePublicValues, {}>;
export type MerkleVerifier = Verifier<MerklePublicInputs, MerklePublicValues, {}>;
export type MerkleProof = Proof<MerklePublicValues>;

function decodePublic(v: any): MerklePublicValues {
  return {
    root: new Field(v.root),
  };
}
